// FVX Solver — fv2 버전
// 고정점 수렴 솔버: 제약 전파 + 상태 수렴

// ============================================================
// 제약(Constraint) 구조체
// ============================================================

struct Constraint {
    name string,
    lo i64,
    hi i64,
    active bool
}

fn make_constraint(name: string, lo: i64, hi: i64) Constraint {
    return Constraint{name: name, lo: lo, hi: hi, active: true}
}

// ============================================================
// 상태(State) 구조체
// ============================================================

struct State {
    id i64,
    value i64,
    mem i64,
    time_tick i64,
    converged bool
}

fn make_state(id: i64, value: i64) State {
    return State{id: id, value: value, mem: 100, time_tick: 0, converged: false}
}

// ============================================================
// 제약 검사
// ============================================================

fn check_constraint(c: Constraint, v: i64) bool {
    if c.active == false {
        return true
    }
    return v >= c.lo && v <= c.hi
}

fn apply_constraint(v: i64, lo: i64, hi: i64) i64 {
    if v < lo {
        return lo
    }
    if v > hi {
        return hi
    }
    return v
}

// ============================================================
// 고정점 수렴 (fixpoint iteration)
// ============================================================

fn fixpoint_step(val: i64, lo: i64, hi: i64, delta: i64) i64 {
    let next = val + delta
    return apply_constraint(next, lo, hi)
}

fn converge(start: i64, target: i64, lo: i64, hi: i64, max_steps: i64) i64 {
    let mut cur = start
    let mut steps = 0
    for steps in 0..max_steps {
        if cur == target {
            return cur
        }
        let diff = target - cur
        let step = 1
        if diff < 0 {
            cur = cur - step
        } else {
            cur = cur + step
        }
        cur = apply_constraint(cur, lo, hi)
    }
    return cur
}

// ============================================================
// 자원 보존 검사 (A2: Resource Conservation)
// ============================================================

fn check_resource(initial: i64, consumed: i64) bool {
    return consumed >= 0 && consumed <= initial
}

