// FVX Pipeline — fv2 버전
// Lex → Parse → Solve → Converge 파이프라인

// ============================================================
// 결과 구조체
// ============================================================

struct PipelineResult {
    ok bool,
    steps i64,
    converged_state i64,
    node_count i64,
    error_code i64
}

fn make_ok_result(steps: i64, state: i64, nodes: i64) PipelineResult {
    return PipelineResult{ok: true, steps: steps, converged_state: state, node_count: nodes, error_code: 0}
}

fn make_err_result(code: i64) PipelineResult {
    return PipelineResult{ok: false, steps: 0, converged_state: -1, node_count: 0, error_code: code}
}

// ============================================================
// 공리 검증 (5개 FVX 공리)
// ============================================================

// A1: 상태 존재 — state_id >= 0
fn axiom_state_exists(state_id: i64) bool {
    return state_id >= 0
}

// A2: 자원 보존 — consumed <= initial
fn axiom_resource_conservation(initial: i64, consumed: i64) bool {
    return consumed >= 0 && consumed <= initial
}

// A3: 제약 완전성 — value in [lo, hi]
fn axiom_constraint_complete(value: i64, lo: i64, hi: i64) bool {
    return value >= lo && value <= hi
}

// A4: 시간 단조성 — time non-decreasing
fn axiom_time_monotone(t_prev: i64, t_next: i64) bool {
    return t_next >= t_prev
}

// A5: 관찰 가능성 — converged state observable
fn axiom_observable(converged: bool) bool {
    return converged
}

// ============================================================
// 수렴 시뮬레이션
// ============================================================

fn simulate_convergence(start: i64, lo: i64, hi: i64, max_steps: i64) PipelineResult {
    // A1 검증
    if axiom_state_exists(start) == false {
        return make_err_result(1)
    }

    let mut val = start
    let mut steps = 0
    let target = (lo + hi) / 2

    for steps in 0..max_steps {
        // A3 검증
        if axiom_constraint_complete(val, lo, hi) == false {
            if val < lo {
                val = lo
            }
            if val > hi {
                val = hi
            }
        }

        // 수렴 체크
        if val == target {
            // A5 검증
            if axiom_observable(true) {
                return make_ok_result(steps, val, steps + 1)
            }
        }

        // 한 스텝 전진
        let diff = target - val
        if diff > 0 {
            val = val + 1
        }
        if diff < 0 {
            val = val - 1
        }
    }

    return make_ok_result(max_steps, val, max_steps)
}

// ============================================================
