#include <string.h>
#include <stdbool.h>
#include <ctype.h>

static char* fvx_concat(const char* a, const char* b) {
  size_t la = strlen(a), lb = strlen(b);
  char* r = (char*)malloc(la+lb+1);
  memcpy(r,a,la); memcpy(r+la,b,lb); r[la+lb]=0; return r;
}
static char* fvx_substr(const char* s, long long start, long long len) {
  long long slen = (long long)strlen(s);
  if(start<0) start=0; if(start>slen) start=slen;
  if(len<0) len=0; if(start+len>slen) len=slen-start;
  char* r = (char*)malloc(len+1); memcpy(r,s+start,len); r[len]=0; return r;
}
static char* fvx_from_char(long long c) {
  char* r = (char*)malloc(2); r[0]=(char)c; r[1]=0; return r;
}
static char* fvx_int_to_str(long long n) {
  char buf[32]; snprintf(buf,sizeof(buf),"%lld",n); return strdup(buf);
}
static char* fvx_read_file(const char* path) {
  FILE* f=fopen(path,"r"); if(!f) return strdup("");
  fseek(f,0,SEEK_END); long sz=ftell(f); rewind(f);
  char* buf=(char*)malloc(sz+1); fread(buf,1,sz,f); buf[sz]=0; fclose(f); return buf;
}




