// FVX Lexer — fv2 버전
// .fvx 소스 파일을 토큰 배열로 변환

// ============================================================
// Token 구조체
// ============================================================

struct Token {
    kind string,
    lexeme string,
    line i64,
    col i64
}

fn make_token(kind: string, lexeme: string, line: i64, col: i64) Token {
    return Token{kind: kind, lexeme: lexeme, line: line, col: col}
}

// ============================================================
// 문자 분류 헬퍼
// ============================================================

fn is_digit(c: i64) bool {
    return c >= 48 && c <= 57
}

fn is_alpha(c: i64) bool {
    return (c >= 65 && c <= 90) || (c >= 97 && c <= 122) || c == 95
}

fn is_alnum(c: i64) bool {
    return is_digit(c) || is_alpha(c)
}

fn is_whitespace(c: i64) bool {
    return c == 32 || c == 9 || c == 13
}

// ============================================================
// Lexer 구조체
// ============================================================

struct Lexer {
    input string,
    pos i64,
    line i64,
    col i64
}

fn new_lexer(input: string) Lexer {
    return Lexer{input: input, pos: 0, line: 1, col: 0}
}

// ============================================================
// 키워드 판별
// ============================================================

fn keyword_kind(word: string) string {
    if word == "state"     { return "STATE" }
    if word == "consume"   { return "CONSUME" }
    if word == "constrain" { return "CONSTRAIN" }
    if word == "evolve"    { return "EVOLVE" }
    if word == "observe"   { return "OBSERVE" }
    if word == "compose"   { return "COMPOSE" }
    if word == "let"       { return "LET" }
    if word == "fn"        { return "FN" }
    if word == "if"        { return "IF" }
    if word == "else"      { return "ELSE" }
    if word == "true"      { return "TRUE" }
    if word == "false"     { return "FALSE" }
    if word == "return"    { return "RETURN" }
    return "IDENT"
}

// ============================================================
// Lexer 테스트 진입점
// ============================================================

fn test_lexer() i64 {
    let pass: i64 = 0
    let fail: i64 = 0

    // Test 1: is_digit
    if is_digit(48) {
        pass = pass + 1
    } else {
        fail = fail + 1
        println("FAIL: is_digit(48)")
    }

    // Test 2: is_digit 경계
    if is_digit(57) {
        pass = pass + 1
    } else {
        fail = fail + 1
        println("FAIL: is_digit(57)")
    }

    // Test 3: 비-digit
    if is_digit(65) {
        fail = fail + 1
        println("FAIL: is_digit(65) should be false")
    } else {
        pass = pass + 1
    }

    // Test 4: is_alpha 대문자
    if is_alpha(65) {
        pass = pass + 1
    } else {
        fail = fail + 1
        println("FAIL: is_alpha(65)")
    }

    // Test 5: is_alpha 소문자
    if is_alpha(97) {
        pass = pass + 1
    } else {
        fail = fail + 1
        println("FAIL: is_alpha(97)")
    }

    // Test 6: is_alpha 언더스코어
