struct Token {
    kind string,
    lexeme string,
    line i64,
    col i64
}

fn make_token(kind: string, lexeme: string, line: i64, col: i64) Token {
    return Token{kind: kind, lexeme: lexeme, line: line, col: col}
}

// ============================================================
// 문자 분류 헬퍼
// ============================================================

fn is_digit(c: i64) bool {
    return c >= 48 && c <= 57
}

fn is_alpha(c: i64) bool {
    return (c >= 65 && c <= 90) || (c >= 97 && c <= 122) || c == 95
}

fn is_alnum(c: i64) bool {
    return is_digit(c) || is_alpha(c)
}

fn is_whitespace(c: i64) bool {
    return c == 32 || c == 9 || c == 13
}

