// inferTypeFromExpression infers C type from AST expression
func (g *Generator) inferTypeFromExpression(expr ast.Expression) string {
	switch e := expr.(type) {
	case *ast.IntegerLiteral:
		return "long long"
	case *ast.FloatLiteral:
		return "double"
	case *ast.StringLiteral:
		return "char*"
	case *ast.BoolLiteral:
		return "bool"
	case *ast.NoneLiteral:
		return "void*"
	case *ast.ArrayExpression:
		if len(e.Elements) > 0 {
			elemType := g.inferTypeFromExpression(e.Elements[0])
			return fmt.Sprintf("%s*", elemType)
		}
		return "void*"
	case *ast.StructExpression:
		return e.Name // struct type name
	case *ast.CallExpression:
		if ident, ok := e.Function.(*ast.Identifier); ok {
			// Check extern func return types
			if retType, exists := g.externFuncTypes[ident.Name]; exists {
				if retType == "f64" {
					return "double"
				} else if retType == "i64" {
					return "long long"
				} else if retType == "string" {
					return "char*"
				} else if retType == "bool" {
					return "bool"
				}
				return retType
			}
			// Check registered function return types
			if retType, exists := g.funcReturnTypes[ident.Name]; exists {
				return retType
			}
		}
		return "long long" // Default for regular function calls
	case *ast.BinaryExpression:
		// If either operand is double, result is double
		leftType := g.inferTypeFromExpression(e.Left)
		rightType := g.inferTypeFromExpression(e.Right)
		if leftType == "double" || rightType == "double" {
			return "double"
		}
		return "long long"
	default:
		// Default to long long for unknown types
		return "long long"
	}
}

// inferFVTypeFromExpression infers FV type from AST expression
func (g *Generator) inferFVTypeFromExpression(expr ast.Expression) string {
	switch e := expr.(type) {
	case *ast.IntegerLiteral:
		return "i64"
	case *ast.FloatLiteral:
		return "f64"
	case *ast.StringLiteral:
		return "string"
	case *ast.BoolLiteral:
		return "bool"
	case *ast.NoneLiteral:
		return "none"
	case *ast.ArrayExpression:
		if len(e.Elements) > 0 {
			elemType := g.inferFVTypeFromExpression(e.Elements[0])
			return fmt.Sprintf("[]%s", elemType)
		}
		return "[]unknown"
	case *ast.CallExpression:
		// Check if it's an extern function call
		if ident, ok := e.Function.(*ast.Identifier); ok {
			if retType, exists := g.externFuncTypes[ident.Name]; exists {
				return retType // Return the extern function's return type

				return retType // Return the extern function's return type
			}
		}
		return "i64" // Default for regular function calls
	case *ast.BinaryExpression:
		// If either operand is f64, result is f64
		leftType := g.inferFVTypeFromExpression(e.Left)
		rightType := g.inferFVTypeFromExpression(e.Right)
		if leftType == "f64" || rightType == "f64" {
			return "f64"
		}
		return "i64"
	default:
		// Default to i64 for unknown types
		return "i64"
	}
}

// escapeString escapes special characters in strings
func escapeString(s string) string {
	s = strings.ReplaceAll(s, "\\", "\\\\")
	s = strings.ReplaceAll(s, "\"", "\\\"")
	s = strings.ReplaceAll(s, "\n", "\\n")
	s = strings.ReplaceAll(s, "\t", "\\t")
	return s
}

