func (l *Lexer) Tokenize() ([]Token, error) {
	var tokens []Token

	for {
		l.skipWhitespaceAndComments()

		if l.isAtEnd() {
			tokens = append(tokens, Token{
				Type:   TknEof,
				Text:   "",
				Line:   l.line,
				Column: l.column,
			})
			break
		}

		token, err := l.nextToken()
		if err != nil {
			return nil, err
		}
		tokens = append(tokens, token)
	}

	return tokens, nil
}

