// FVX Runner — fv2 버전
// fvx run <file.fvx>: 파일을 읽어 lexer → solver → pipeline 실행
// 현재: lexer 단계 구현 (토큰 스캔 & 통계)

// ============================================================
// 토큰 분류 헬퍼 (lexer.fv에서 재사용)
// ============================================================

fn is_digit(c: i64) bool {
    return c >= 48 && c <= 57
}

fn is_alpha(c: i64) bool {
    return (c >= 65 && c <= 90) || (c >= 97 && c <= 122) || c == 95
}

fn is_alnum(c: i64) bool {
    return is_digit(c) || is_alpha(c)
}

fn is_whitespace(c: i64) bool {
    return c == 32 || c == 9 || c == 13
}

fn char_at(s: string, pos: i64) i64 {
    let n = str_len(s)
    if pos < 0 { return 0 }
    if pos >= n { return 0 }
    return str_at(s, pos)
}

fn scan_word(s: string, start: i64) string {
    let n = str_len(s)
    let mut end = start
    let mut running = true
    for i in 0..4096 {
        if running == false {
            // done
        } else {
            if end >= n {
                running = false
            } else {
                let c = str_at(s, end)
                if is_alnum(c) {
                    end = end + 1
                } else {
                    running = false
                }
            }
        }
    }
    let length = end - start
    return str_sub(s, start, length)
}

fn scan_number(s: string, start: i64) string {
    let n = str_len(s)
    let mut end = start
    let mut running = true
    for i in 0..4096 {
        if running == false {
            // done
        } else {
            if end >= n {
                running = false
            } else {
                let c = str_at(s, end)
                if is_digit(c) {
                    end = end + 1
                } else {
                    running = false
                }
            }
        }
    }
    let length = end - start
    return str_sub(s, start, length)
}

// ============================================================
// FVX 키워드 분류
// ============================================================

fn fvx_keyword_kind(word: string) string {
    if str_eq(word, "AXIOM")      { return "AXIOM" }
    if str_eq(word, "INVARIANT")  { return "INVARIANT" }
    if str_eq(word, "MATCH")      { return "MATCH" }
    if str_eq(word, "SOLVE")      { return "SOLVE" }
    if str_eq(word, "PROOF")      { return "PROOF" }
    if str_eq(word, "DEFINE")     { return "DEFINE" }
    if str_eq(word, "ASSERT")     { return "ASSERT" }
    if str_eq(word, "FORALL")     { return "FORALL" }
    if str_eq(word, "CONVERGE")   { return "CONVERGE" }
    if str_eq(word, "EXPECTED")   { return "EXPECTED" }
    if str_eq(word, "STRATEGY")   { return "STRATEGY" }
    if str_eq(word, "BRIDGE")     { return "BRIDGE" }
    if str_eq(word, "NODE")       { return "NODE" }
    if str_eq(word, "EVOLVE")     { return "EVOLVE" }
    if str_eq(word, "CLAMP")      { return "CLAMP" }
    if str_eq(word, "IR")         { return "IR" }
    return "IDENT"
}

// ============================================================
// 토큰 카운터 구조체
// ============================================================

struct TokenStats {
    total i64,
    keywords i64,
    idents i64,
    numbers i64,
    symbols i64,
    errors i64
}

fn make_stats() TokenStats {
    return TokenStats{total: 0, keywords: 0, idents: 0, numbers: 0, symbols: 0, errors: 0}
}

// ============================================================
// 단일 토큰 스캔 (pos 반환)
// ============================================================

struct ScanToken {
    kind string,
    next_pos i64
}

fn scan_next(src: string, pos: i64) ScanToken {
    let n = str_len(src)

    // 공백 및 주석 스킵
    let mut cur = pos
    let mut skipping = true
    for i in 0..65536 {
        if skipping == false {
            // done
        } else {
            if cur >= n {
                skipping = false
            } else {
                let c = char_at(src, cur)
                // 공백/탭/CR/LF 스킵
                if is_whitespace(c) || c == 10 {
                    cur = cur + 1
                } else {
                    // // 주석 스킵
                    if c == 47 {
                        let c2 = char_at(src, cur + 1)
                        if c2 == 47 {
                            // 줄 끝까지 스킵
                            for j in 0..4096 {
                                if cur >= n {
                                    // done
                                } else {
                                    let cc = char_at(src, cur)
                                    if cc == 10 {
                                        cur = cur + 1
                                    } else {
                                        cur = cur + 1
                                    }
                                }
                            }
                        } else {
                            skipping = false
                        }
                    } else {
                        skipping = false
                    }
                }
            }
        }
    }

    if cur >= n {
        return ScanToken{kind: "EOF", next_pos: cur}
    }

    let ch = char_at(src, cur)

    // 숫자
    if is_digit(ch) {
        let num = scan_number(src, cur)
        let nlen = str_len(num)
        return ScanToken{kind: "INT", next_pos: cur + nlen}
    }

    // 식별자/키워드
    if is_alpha(ch) {
        let word = scan_word(src, cur)
        let wlen = str_len(word)
        let kind = fvx_keyword_kind(word)
        return ScanToken{kind: kind, next_pos: cur + wlen}
    }

    // 문자열 리터럴 스킵 (따옴표 안쪽)
    if ch == 34 {
        let mut end = cur + 1
        let mut in_str = true
        for i in 0..4096 {
            if in_str == false {
                // done
            } else {
                if end >= n {
                    in_str = false
                } else {
                    let sc = char_at(src, end)
                    if sc == 34 {
                        end = end + 1
                        in_str = false
                    } else {
                        end = end + 1
                    }
                }
            }
        }
        return ScanToken{kind: "STRING", next_pos: end}
    }

    // 기타 심볼 (한 글자씩)
    return ScanToken{kind: "SYMBOL", next_pos: cur + 1}
}

// ============================================================
// FVX 파일 분석 실행
// ============================================================

fn run_fvx(path: string) i64 {
    println("=== FVX Runner ===")
    println(str_concat("파일: ", path))

    let src = read_file(path)
    let src_len = str_len(src)

    if src_len == 0 {
        println("ERROR: 파일 읽기 실패 또는 빈 파일")
        return 1
    }

    println(str_concat("소스 길이: ", int_to_str(src_len)))
    println("")

    // 토큰 스캔
    let mut stats = make_stats()
    let mut pos = 0
    let mut scanning = true

    for i in 0..65536 {
        if scanning == false {
            // done
        } else {
            let tok = scan_next(src, pos)

            if str_eq(tok.kind, "EOF") {
                scanning = false
            } else {
                stats = TokenStats{
                    total: stats.total + 1,
                    keywords: stats.keywords,
                    idents: stats.idents,
                    numbers: stats.numbers,
                    symbols: stats.symbols,
                    errors: stats.errors
                }

                // 카테고리 분류
                if str_eq(tok.kind, "IDENT") {
                    stats = TokenStats{
                        total: stats.total,
                        keywords: stats.keywords,
                        idents: stats.idents + 1,
                        numbers: stats.numbers,
                        symbols: stats.symbols,
                        errors: stats.errors
                    }
                } else {
                    if str_eq(tok.kind, "INT") {
                        stats = TokenStats{
                            total: stats.total,
                            keywords: stats.keywords,
                            idents: stats.idents,
                            numbers: stats.numbers + 1,
                            symbols: stats.symbols,
                            errors: stats.errors
                        }
                    } else {
                        if str_eq(tok.kind, "SYMBOL") || str_eq(tok.kind, "STRING") {
                            stats = TokenStats{
                                total: stats.total,
                                keywords: stats.keywords,
                                idents: stats.idents,
                                numbers: stats.numbers,
                                symbols: stats.symbols + 1,
                                errors: stats.errors
                            }
                        } else {
                            stats = TokenStats{
                                total: stats.total,
                                keywords: stats.keywords + 1,
                                idents: stats.idents,
                                numbers: stats.numbers,
                                symbols: stats.symbols,
                                errors: stats.errors
                            }
                        }
                    }
                }

                pos = tok.next_pos
            }
        }
    }

    // 결과 출력
    println("=== 렉서 분석 결과 ===")
    println(str_concat("총 토큰:   ", int_to_str(stats.total)))
    println(str_concat("키워드:    ", int_to_str(stats.keywords)))
    println(str_concat("식별자:    ", int_to_str(stats.idents)))
    println(str_concat("숫자:      ", int_to_str(stats.numbers)))
    println(str_concat("심볼/문자: ", int_to_str(stats.symbols)))
    println("")

    // Axiom 섹션 검출
    let has_axiom = stats.keywords > 0
    let has_solve = stats.keywords > 2
    let has_proof = stats.keywords > 4

    println("=== FVX 구조 검증 ===")
    if has_axiom {
        println("[OK] AXIOM 섹션 감지")
    } else {
        println("[WARN] AXIOM 섹션 없음")
    }
    if has_solve {
        println("[OK] SOLVE 섹션 감지")
    } else {
        println("[WARN] SOLVE 섹션 없음")
    }
    if has_proof {
        println("[OK] PROOF 섹션 감지")
    } else {
        println("[WARN] PROOF 섹션 없음")
    }

    println("")
    println("=== 수렴 시뮬레이션 ===")

    // 제약 기반 수렴: 키워드 수가 예상 범위에 있어야 함
    let expected_min: i64 = 5
    let expected_max: i64 = 100

    if stats.keywords >= expected_min && stats.keywords <= expected_max {
        println(str_concat("수렴 상태: STABLE (키워드=" , int_to_str(stats.keywords)))
        println("결과: VERIFIED")
        return 0
    } else {
        println("수렴 상태: UNSTABLE")
        println("결과: UNVERIFIED")
        return 1
    }
}

fn main() {
    let path = "/data/data/com.termux/files/home/.projects/core/fvx/examples/range_check.fvx"
    let result = run_fvx(path)
    if result == 0 {
        println("")
        println("✓ FVX 검증 완료: PASSED")
    } else {
        println("")
        println("✗ FVX 검증 실패: FAILED")
    }
}

