   966→// parseType parses a type
   967→func (p *Parser) parseType() *ast.Type {
   968→	// Handle option types (?)
   969→	isOption := p.match(lexer.TknQuestion)
   970→
   971→	// Get base type
   972→	var typeName string
   973→	if p.match(lexer.TknIdentifier) {
   974→		typeName = p.previous().Text
   975→	} else {
   976→		typeName = "unknown"
   977→	}
   978→
   979→	// Handle array types (prefix [])
   980→	isArray := false
   981→	if p.check(lexer.TknLBracket) {
   982→		p.advance()
   983→		if p.match(lexer.TknRBracket) {
   984→			isArray = true
   985→		} else {
   986→			p.pos-- // backtrack
   987→		}
   988→	}
   989→
   990→	return &ast.Type{
   991→		Name:       typeName,
   992→		IsOption:   isOption,
   993→		IsArray:    isArray,
   994→		IsPrimitive: isPrimitiveType(typeName),
   995→	}
