   500→				len(ft.ParamTypes), len(call.Arguments),
   501→			))
   502→		}
   503→
   504→		// Check argument types
   505→		for i, arg := range call.Arguments {
   506→			if i < len(ft.ParamTypes) {
   507→				argType := c.checkExpression(arg)
   508→				expectedType := ft.ParamTypes[i]
